// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertAll;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** A renewed physical reader remains part of the same logical iterator and its accumulated work evidence. */
class LmdbPersistentAdjacencyTelemetryRenewalTest {

	@TempDir
	Path directory;

	@ParameterizedTest(name = "ordinary reader telemetry survives renewal, bulk={0}")
	@ValueSource(booleans = { false, true })
	void ordinaryCommitRenewalPreservesMonotoneBalancedTelemetry(boolean bulk) throws Exception {
		try (TripleStore store = new TripleStore(directory.toFile(), new LmdbStoreConfig("spoc"), null)) {
			store.startTransaction();
			for (long subject = 10; subject <= 15; subject++) {
				store.storeTriple(subject, 20, subject + 20, subject == 11 || subject == 13 ? 8 : 7, true);
			}
			store.commit();

			try (Txn txn = store.getTxnManager().createReadTxn();
					RecordIterator iterator = store.getTriples(txn, -1, -1, -1, 7, true)) {
				List<long[]> delivered = new ArrayList<>();
				List<Work> observations = new ArrayList<>();
				if (bulk) {
					assertThat(pull(iterator, true, 3, delivered)).isEqualTo(3);
				} else {
					for (int index = 0; index < 3; index++) {
						assertThat(pull(iterator, false, 1, delivered)).isEqualTo(1);
						observations.add(Work.read(iterator));
					}
				}
				Work beforeCommit = Work.read(iterator);
				observations.add(beforeCommit);
				assertThat(beforeCommit).as("real residual-context work precedes the renewal")
						.isEqualTo(new Work(5, 3, 2));
				long versionBeforeCommit = txn.version();
				long leaseBeforeCommit = txn.lease();
				long nativeTransactionBeforeCommit = txn.nativeTransactionId();
				assertThat(txn.snapshotRevision()).as("this is an ordinary unpinned reader").isEqualTo(-1L);

				store.startTransaction();
				store.storeTriple(16, 20, 36, 7, true);
				store.commit();

				assertAll("the normal commit renews the existing reader rather than replacing its owner",
						() -> assertThat(txn.version()).isGreaterThan(versionBeforeCommit),
						() -> assertThat(txn.nativeTransactionId()).isGreaterThan(nativeTransactionBeforeCommit),
						() -> assertThat(txn.lease()).isEqualTo(leaseBeforeCommit));
				int count;
				do {
					count = pull(iterator, bulk, bulk ? 3 : 1, delivered);
					observations.add(Work.read(iterator));
				} while (count != 0);

				assertAll("one logical scan retains its complete work history across the ordinary renewal",
						() -> assertThat(delivered).usingRecursiveComparison()
								.isEqualTo(List.of(
										new long[] { 10, 20, 30, 7 },
										new long[] { 12, 20, 32, 7 },
										new long[] { 14, 20, 34, 7 },
										new long[] { 15, 20, 35, 7 },
										new long[] { 16, 20, 36, 7 })),
						() -> assertThat(observations).allSatisfy(work -> assertThat(work.scanned())
								.as("every observed scan count equals matched plus filtered work")
								.isEqualTo(work.matched() + work.filtered())),
						() -> assertMonotone(observations),
						() -> assertThat(Work.read(iterator).matched()).isEqualTo(delivered.size()));
			}
		}
	}

	private static int pull(RecordIterator iterator, boolean bulk, int capacity, List<long[]> delivered) {
		if (!bulk) {
			long[] next = iterator.next();
			if (next == null) {
				return 0;
			}
			delivered.add(next.clone());
			return 1;
		}
		long[] buffer = new long[capacity * 4];
		int count = iterator.fill(buffer, capacity);
		for (int index = 0; index < count; index++) {
			delivered.add(Arrays.copyOfRange(buffer, index * 4, (index + 1) * 4));
		}
		return count;
	}

	private static void assertMonotone(List<Work> observations) {
		for (int index = 1; index < observations.size(); index++) {
			Work previous = observations.get(index - 1);
			Work current = observations.get(index);
			assertThat(current.scanned()).as("scanned work at observation %s", index)
					.isGreaterThanOrEqualTo(previous.scanned());
			assertThat(current.matched()).as("matched work at observation %s", index)
					.isGreaterThanOrEqualTo(previous.matched());
			assertThat(current.filtered()).as("filtered work at observation %s", index)
					.isGreaterThanOrEqualTo(previous.filtered());
		}
	}

	private record Work(long scanned, long matched, long filtered) {
		private static Work read(RecordIterator iterator) {
			return new Work(iterator.getSourceRowsScannedActual(), iterator.getSourceRowsMatchedActual(),
					iterator.getSourceRowsFilteredActual());
		}
	}
}
